    44→    registerWsClient(userId, ws);
    45→    ws.send(JSON.stringify({ type: 'connected', message: 'متصل بالإشعارات الفورية' }));
    46→    ws.on('close', () => unregisterWsClient(userId));
    47→    ws.on('error', () => unregisterWsClient(userId));
    48→  } catch {
    49→    ws.close();
    50→  }
    51→});
