   108→  app.use(express.static(clientDist, {
   109→    maxAge: '1y',
   110→    immutable: true,
   111→    setHeaders: (res, filePath) => {
   112→      if (filePath.endsWith('.html')) {
   113→        res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
   114→      }
   115→    },
   116→  }));
   117→
   118→  app.get('/sitemap.xml', (req, res) => res.sendFile(path.join(clientDist, 'sitemap.xml')));
   119→  app.get('/robots.txt',  (req, res) => res.sendFile(path.join(clientDist, 'robots.txt')));
   120→
   121→  app.get('*', (req, res) => {
   122→    if (req.path.startsWith('/api')) return res.status(404).json({ message: 'Not found' });
